  // ==========================================
  // MODULE 02: 長短高矮與直接比較 (起點對齊)
  // ==========================================
  function renderW02() {
    let redLength = 8;
    let blueLength = 6;
    let redOffset = 50; // starts misaligned

    labStage.innerHTML = `
      <div style="width:100%; max-width:600px; height:240px; background:#fff; border:2px dashed #cbd5e1; border-radius:16px; position:relative; overflow:hidden; padding:20px;">
        <!-- Start Alignment Red Line -->
        <div style="position:absolute; left:60px; top:0; bottom:0; width:4px; background:#ef4444; z-index:10;">
          <span style="position:absolute; top:8px; left:8px; font-size:0.75rem; font-weight:800; color:#ef4444; background:#fee2e2; padding:2px 6px; border-radius:4px; white-space:nowrap;">起點基準線</span>
        </div>

        <!-- Red Pencil -->
        <div id="redPencil" style="position:absolute; left:${60 + redOffset}px; top:50px; height:36px; width:${redLength * 40}px; background:linear-gradient(90deg, #f87171, #ef4444); border-radius:6px 0 0 6px; display:flex; align-items:center; justify-content:space-between; padding:0 8px; color:#fff; font-weight:800; box-shadow:0 4px 10px rgba(239,68,68,0.3); cursor:grab; transition:left 0.2s;">
          <span>✏️ 紅鉛筆 (${redLength}格)</span>
          <span style="border-left:12px solid #ef4444; border-top:18px solid transparent; border-bottom:18px solid transparent; position:absolute; right:-12px;"></span>
        </div>

        <!-- Blue Pencil (Fixed at baseline) -->
        <div id="bluePencil" style="position:absolute; left:60px; top:130px; height:36px; width:${blueLength * 40}px; background:linear-gradient(90deg, #60a5fa, #3b82f6); border-radius:6px 0 0 6px; display:flex; align-items:center; justify-content:space-between; padding:0 8px; color:#fff; font-weight:800; box-shadow:0 4px 10px rgba(59,130,246,0.3);">
          <span>✏️ 藍鉛筆 (${blueLength}格)</span>
          <span style="border-left:12px solid #3b82f6; border-top:18px solid transparent; border-bottom:18px solid transparent; position:absolute; right:-12px;"></span>
        </div>
      </div>
      <div id="w02Status" style="margin-top:12px; font-size:1rem; font-weight:800; color:#991b1b; background:#fef2f2; padding:8px 16px; border-radius:12px;">
        ⚠️ 紅鉛筆起點沒有對齊紅線！點擊按鈕或滑桿將起點對齊！
      </div>
    `;

    controlPanel.innerHTML = `
      <button id="btnAlign" class="btn-ctrl btn-ctrl-accent"><i class="fa-solid fa-align-left"></i> 一鍵對齊起點線！</button>
      <div class="slider-group">
        <label>調整紅筆長度：</label>
        <input type="range" id="sliderRed" class="slider-custom" min="4" max="10" value="${redLength}">
        <span id="badgeRed" class="val-badge">${redLength}格</span>
      </div>
      <div class="slider-group">
        <label>調整藍筆長度：</label>
        <input type="range" id="sliderBlue" class="slider-custom" min="4" max="10" value="${blueLength}">
        <span id="badgeBlue" class="val-badge">${blueLength}格</span>
      </div>
    `;

    const btnAlign = document.getElementById("btnAlign");
    const sliderRed = document.getElementById("sliderRed");
    const sliderBlue = document.getElementById("sliderBlue");
    const badgeRed = document.getElementById("badgeRed");
    const badgeBlue = document.getElementById("badgeBlue");
    const redPencil = document.getElementById("redPencil");
    const bluePencil = document.getElementById("bluePencil");
    const status = document.getElementById("w02Status");

    function renderPencils() {
      redPencil.style.left = `${60 + redOffset}px`;
      redPencil.style.width = `${redLength * 40}px`;
      bluePencil.style.width = `${blueLength * 40}px`;
      badgeRed.textContent = `${redLength}格`;
      badgeBlue.textContent = `${blueLength}格`;

      if (redOffset === 0) {
        if (redLength > blueLength) {
          status.style.color = "#166534";
          status.style.background = "#f0fdf4";
          status.innerHTML = `✨ 起點已對齊！紅鉛筆伸出較遠，【紅鉛筆比藍鉛筆長 ${redLength - blueLength} 格】！`;
        } else if (redLength < blueLength) {
          status.style.color = "#1e40af";
          status.style.background = "#eff6ff";
          status.innerHTML = `✨ 起點已對齊！藍鉛筆伸出較遠，【藍鉛筆比紅鉛筆長 ${blueLength - redLength} 格】！`;
        } else {
          status.style.color = "#854d0e";
          status.style.background = "#fefce8";
          status.innerHTML = `✨ 起點已對齊！兩支筆終點一樣遠，【兩支筆一樣長】！`;
        }
        celebrate();
      } else {
        status.style.color = "#991b1b";
        status.style.background = "#fef2f2";
        status.innerHTML = `⚠️ 紅鉛筆起點沒有對齊紅線！起點沒對齊，比終點是不公平的！`;
      }
    }

    btnAlign.addEventListener("click", () => {
      redOffset = 0;
      renderPencils();
      showToast("起點已嚴格對齊基準線！現在可以公平看終點比較長短了！");
    });

    sliderRed.addEventListener("input", (e) => {
      redLength = parseInt(e.target.value);
      renderPencils();
    });

    sliderBlue.addEventListener("input", (e) => {
      blueLength = parseInt(e.target.value);
      renderPencils();
    });
  }

  // ==========================================
  // MODULE 03: 十格陣與數感結構 (5與10基準)
  // ==========================================
  function renderW03() {
    let count = 8;

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:16px;">
        <!-- 2x5 Ten Frame Grid -->
        <div id="tenFrame" style="display:grid; grid-template-columns:repeat(5, 70px); grid-template-rows:repeat(2, 70px); gap:6px; background:#e2e8f0; padding:10px; border-radius:18px; border:4px solid #334155; box-shadow:0 8px 20px rgba(0,0,0,0.1);">
          <!-- 10 cells generated in JS -->
        </div>
        <div id="w03Readout" style="font-size:1.2rem; font-weight:800; color:#1e3a8a; background:#eff6ff; padding:10px 24px; border-radius:14px; border:2px solid #bfdbfe;">
          <!-- Readout text -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <div class="slider-group">
        <label>圓片數量：</label>
        <input type="range" id="sliderCount" class="slider-custom" min="0" max="10" value="${count}">
        <span id="badgeCount" class="val-badge">${count}顆</span>
      </div>
      <button id="btnAdd" class="btn-ctrl btn-ctrl-accent"><i class="fa-solid fa-plus"></i> 加 1 顆</button>
      <button id="btnMinus" class="btn-ctrl"><i class="fa-solid fa-minus"></i> 減 1 顆</button>
      <button id="btnClear" class="btn-ctrl"><i class="fa-solid fa-rotate-left"></i> 清空</button>
    `;

    const tenFrame = document.getElementById("tenFrame");
    const readout = document.getElementById("w03Readout");
    const sliderCount = document.getElementById("sliderCount");
    const badgeCount = document.getElementById("badgeCount");
    const btnAdd = document.getElementById("btnAdd");
    const btnMinus = document.getElementById("btnMinus");
    const btnClear = document.getElementById("btnClear");

    function renderGrid() {
      tenFrame.innerHTML = "";
      for (let i = 0; i < 10; i++) {
        const cell = document.createElement("div");
        cell.style.cssText = "background:#fff; border-radius:12px; display:flex; align-items:center; justify-content:center; font-size:2.5rem; transition:all 0.2s; box-shadow:inset 0 2px 4px rgba(0,0,0,0.06);";
        if (i < count) {
          cell.textContent = i < 5 ? "🔴" : "🔵";
          cell.style.background = i < 5 ? "#fee2e2" : "#dbeafe";
        }
        tenFrame.appendChild(cell);
      }

      badgeCount.textContent = `${count}顆`;
      sliderCount.value = count;

      const topRow = Math.min(count, 5);
      const bottomRow = Math.max(0, count - 5);
      const empty = 10 - count;

      readout.innerHTML = `
        上一排：<b>${topRow}</b> 顆 ＋ 下一排：<b>${bottomRow}</b> 顆 ＝ 總共 <b>${count}</b> 顆 | 還差 <b>${empty}</b> 顆滿 10！
      `;
      celebrate();
    }

    sliderCount.addEventListener("input", (e) => {
      count = parseInt(e.target.value);
      renderGrid();
    });

    btnAdd.addEventListener("click", () => {
      if (count < 10) { count++; renderGrid(); }
    });

    btnMinus.addEventListener("click", () => {
      if (count > 0) { count--; renderGrid(); }
    });

    btnClear.addEventListener("click", () => {
      count = 0;
      renderGrid();
    });

    renderGrid();
  }

  // ==========================================
  // MODULE 04: 單雙數兩兩配對
  // ==========================================
  function renderW04() {
    let items = 7;

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:16px; width:100%;">
        <div id="socksContainer" style="display:flex; flex-wrap:wrap; justify-content:center; gap:14px; max-width:600px; min-height:160px; padding:16px; background:#fff; border-radius:16px; border:2px solid #e2e8f0;">
          <!-- Socks generated in JS -->
        </div>
        <div id="w04Result" style="font-size:1.15rem; font-weight:800; padding:10px 24px; border-radius:14px;">
          <!-- Result generated in JS -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <div class="slider-group">
        <label>襪子總數：</label>
        <input type="range" id="sliderSocks" class="slider-custom" min="1" max="12" value="${items}">
        <span id="badgeSocks" class="val-badge">${items}隻</span>
      </div>
      <button id="btnAddSock" class="btn-ctrl btn-ctrl-accent"><i class="fa-solid fa-plus"></i> 加 1 隻 🧦</button>
      <button id="btnMinusSock" class="btn-ctrl"><i class="fa-solid fa-minus"></i> 減 1 隻 🧦</button>
    `;

    const container = document.getElementById("socksContainer");
    const result = document.getElementById("w04Result");
    const slider = document.getElementById("sliderSocks");
    const badge = document.getElementById("badgeSocks");
    const btnAdd = document.getElementById("btnAddSock");
    const btnMinus = document.getElementById("btnMinusSock");

    function renderSocks() {
      container.innerHTML = "";
      const pairs = Math.floor(items / 2);
      const remainder = items % 2;

      for (let p = 0; p < pairs; p++) {
        const pairBox = document.createElement("div");
        pairBox.style.cssText = "display:flex; gap:4px; padding:6px 10px; background:#dcfce7; border:2px solid #22c55e; border-radius:12px; align-items:center;";
        pairBox.innerHTML = `
          <span style="font-size:2rem;">🧦</span>
          <span style="font-size:2rem;">🧦</span>
          <span style="font-size:0.75rem; font-weight:800; color:#15803d; margin-left:4px;">成雙 ✓</span>
        `;
        container.appendChild(pairBox);
      }

      if (remainder === 1) {
        const singleBox = document.createElement("div");
        singleBox.style.cssText = "display:flex; padding:6px 12px; background:#fee2e2; border:2px dashed #ef4444; border-radius:12px; align-items:center; animation:pulse 1s infinite;";
        singleBox.innerHTML = `
          <span style="font-size:2rem;">🧦</span>
          <span style="font-size:0.75rem; font-weight:800; color:#b91c1c; margin-left:4px;">落單 1 隻 ❓</span>
        `;
        container.appendChild(singleBox);
      }

      badge.textContent = `${items}隻`;
      slider.value = items;

      if (remainder === 0) {
        result.style.background = "#dcfce7";
        result.style.color = "#15803d";
        result.innerHTML = `🎉 ${items} 隻襪子剛好配成 <b>${pairs}</b> 雙，沒有剩下 ➜ 是【雙數】！`;
      } else {
        result.style.background = "#fee2e2";
        result.style.color = "#b91c1c";
        result.innerHTML = `👀 ${items} 隻襪子配成 <b>${pairs}</b> 雙後，多出了 <b>1</b> 隻 ➜ 是【單數】！`;
      }
      celebrate();
    }

    slider.addEventListener("input", (e) => { items = parseInt(e.target.value); renderSocks(); });
    btnAdd.addEventListener("click", () => { if (items < 12) { items++; renderSocks(); } });
    btnMinus.addEventListener("click", () => { if (items > 1) { items--; renderSocks(); } });

    renderSocks();
  }

  // ==========================================
  // MODULE 05: 數的分與合與天平 (7個葡撻)
  // ==========================================
  function renderW05() {
    let leftCount = 3;
    const TOTAL = 7;

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:20px; width:100%;">
        <!-- Plates Container -->
        <div style="display:flex; justify-content:space-around; align-items:center; width:100%; max-width:600px;">
          <!-- Red Plate -->
          <div style="display:flex; flex-direction:column; align-items:center; gap:8px;">
            <div style="font-weight:800; font-size:1.1rem; color:#dc2626;">🔴 紅盤子 (<span id="txtLeft">${leftCount}</span>個)</div>
            <div id="plateLeft" style="width:180px; height:180px; background:#fee2e2; border:4px solid #ef4444; border-radius:50%; display:flex; flex-wrap:wrap; align-items:center; justify-content:center; padding:16px; gap:8px; box-shadow:0 8px 16px rgba(0,0,0,0.06);">
              <!-- Tart items -->
            </div>
          </div>

          <div style="font-size:2.5rem; color:#f59e0b; font-weight:900;">⚖️</div>

          <!-- Blue Plate -->
          <div style="display:flex; flex-direction:column; align-items:center; gap:8px;">
            <div style="font-weight:800; font-size:1.1rem; color:#2563eb;">🔵 藍盤子 (<span id="txtRight">${TOTAL - leftCount}</span>個)</div>
            <div id="plateRight" style="width:180px; height:180px; background:#dbeafe; border:4px solid #3b82f6; border-radius:50%; display:flex; flex-wrap:wrap; align-items:center; justify-content:center; padding:16px; gap:8px; box-shadow:0 8px 16px rgba(0,0,0,0.06);">
              <!-- Tart items -->
            </div>
          </div>
        </div>

        <div id="w05Formula" style="font-size:1.3rem; font-weight:800; color:#1e3a8a; background:#f0fdf4; padding:10px 24px; border-radius:14px; border:2px solid #86efac;">
          <!-- Formula -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <div class="slider-group">
        <label>左盤數量：</label>
        <input type="range" id="sliderPart" class="slider-custom" min="1" max="6" value="${leftCount}">
        <span id="badgePart" class="val-badge">${leftCount}個</span>
      </div>
      <button id="btnShiftLeft" class="btn-ctrl"><i class="fa-solid fa-arrow-left"></i> 左移 1 個</button>
      <button id="btnShiftRight" class="btn-ctrl"><i class="fa-solid fa-arrow-right"></i> 右移 1 個</button>
    `;

    const plateLeft = document.getElementById("plateLeft");
    const plateRight = document.getElementById("plateRight");
    const txtLeft = document.getElementById("txtLeft");
    const txtRight = document.getElementById("txtRight");
    const formula = document.getElementById("w05Formula");
    const slider = document.getElementById("sliderPart");
    const badge = document.getElementById("badgePart");
    const btnShiftLeft = document.getElementById("btnShiftLeft");
    const btnShiftRight = document.getElementById("btnShiftRight");

    function renderPlates() {
      plateLeft.innerHTML = "";
      plateRight.innerHTML = "";
      const rightCount = TOTAL - leftCount;

      txtLeft.textContent = leftCount;
      txtRight.textContent = rightCount;
      badge.textContent = `${leftCount}個`;
      slider.value = leftCount;

      for (let i = 0; i < leftCount; i++) {
        plateLeft.innerHTML += '<span style="font-size:2.2rem;">🥧</span>';
      }
      for (let i = 0; i < rightCount; i++) {
        plateRight.innerHTML += '<span style="font-size:2.2rem;">🥧</span>';
      }

      formula.innerHTML = `7 個葡撻分成：<b>${leftCount}</b> 和 <b>${rightCount}</b> （算式：${leftCount} ＋ ${rightCount} ＝ 7，天平平衡！）`;
      celebrate();
    }

    slider.addEventListener("input", (e) => {
      leftCount = parseInt(e.target.value);
      renderPlates();
    });

    btnShiftLeft.addEventListener("click", () => {
      if (leftCount < 6) { leftCount++; renderPlates(); }
    });

    btnShiftRight.addEventListener("click", () => {
      if (leftCount > 1) { leftCount--; renderPlates(); }
    });

    renderPlates();
  }

  // ==========================================
  // MODULE 06: 基本加法與交換律 (3 + 2 = 2 + 3)
  // ==========================================
  function renderW06() {
    let numA = 3;
    let numB = 2;
    let swapped = false;

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:16px;">
        <div id="cubesBox" style="display:flex; gap:12px; align-items:center; padding:20px; background:#fff; border-radius:18px; border:2px solid #e2e8f0; min-height:140px;">
          <!-- Cubes rendered in JS -->
        </div>
        <div id="w06Readout" style="font-size:1.3rem; font-weight:800; color:#1e3a8a; background:#eff6ff; padding:10px 24px; border-radius:14px; border:2px solid #bfdbfe;">
          <!-- Readout -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <div class="slider-group">
        <label>紅積木數量：</label>
        <input type="range" id="sliderA" class="slider-custom" min="1" max="5" value="${numA}">
        <span id="badgeA" class="val-badge">${numA}</span>
      </div>
      <div class="slider-group">
        <label>黃積木數量：</label>
        <input type="range" id="sliderB" class="slider-custom" min="1" max="5" value="${numB}">
        <span id="badgeB" class="val-badge">${numB}</span>
      </div>
      <button id="btnSwap" class="btn-ctrl btn-ctrl-accent"><i class="fa-solid fa-arrows-rotate"></i> 🔄 交換順序 (交換律)</button>
    `;

    const cubesBox = document.getElementById("cubesBox");
    const readout = document.getElementById("w06Readout");
    const sliderA = document.getElementById("sliderA");
    const sliderB = document.getElementById("sliderB");
    const badgeA = document.getElementById("badgeA");
    const badgeB = document.getElementById("badgeB");
    const btnSwap = document.getElementById("btnSwap");

    function renderCubes() {
      cubesBox.innerHTML = "";
      const leftPart = swapped ? numB : numA;
      const rightPart = swapped ? numA : numB;
      const leftColor = swapped ? "🟡" : "🔴";
      const rightColor = swapped ? "🔴" : "🟡";

      // Left group
      const leftDiv = document.createElement("div");
      leftDiv.style.cssText = "display:flex; gap:6px; padding:10px; background:#f1f5f9; border-radius:12px;";
      for (let i = 0; i < leftPart; i++) leftDiv.innerHTML += `<span style="font-size:2.2rem;">${leftColor}</span>`;
      cubesBox.appendChild(leftDiv);

      cubesBox.innerHTML += '<span style="font-size:2rem; font-weight:900; color:#64748b;">＋</span>';

      // Right group
      const rightDiv = document.createElement("div");
      rightDiv.style.cssText = "display:flex; gap:6px; padding:10px; background:#f1f5f9; border-radius:12px;";
      for (let i = 0; i < rightPart; i++) rightDiv.innerHTML += `<span style="font-size:2.2rem;">${rightColor}</span>`;
      cubesBox.appendChild(rightDiv);

      const total = numA + numB;
      badgeA.textContent = numA;
      badgeB.textContent = numB;

      readout.innerHTML = `
        算式：<b>${leftPart}</b> ＋ <b>${rightPart}</b> ＝ <b>${total}</b> 
        （${swapped ? "交換位置後，總數依然是 " + total : "點擊交換按鈕看交換律"}）
      `;
      celebrate();
    }

    sliderA.addEventListener("input", (e) => { numA = parseInt(e.target.value); renderCubes(); });
    sliderB.addEventListener("input", (e) => { numB = parseInt(e.target.value); renderCubes(); });
    btnSwap.addEventListener("click", () => {
      swapped = !swapped;
      renderCubes();
      showToast("加數位置交換了，但積木總數完全相同！加法交換律成功驗證！");
    });

    renderCubes();
  }

  // ==========================================
  // MODULE 07: 基本減法與神奇 0 (魚缸撈魚)
  // ==========================================
  function renderW07() {
    let fishCount = 5;
    const INITIAL = 5;

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:16px;">
        <div id="aquarium" style="width:100%; max-width:540px; height:200px; background:linear-gradient(180deg, #bae6fd 0%, #38bdf8 100%); border:4px solid #0284c7; border-radius:30px; position:relative; overflow:hidden; display:flex; align-items:center; justify-content:space-around; padding:20px; box-shadow:0 10px 25px rgba(2,132,199,0.3);">
          <!-- Fish elements rendered here -->
        </div>
        <div id="w07Formula" style="font-size:1.3rem; font-weight:800; color:#1e3a8a; background:#eff6ff; padding:10px 24px; border-radius:14px; border:2px solid #bfdbfe;">
          <!-- Formula -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <button id="btnNetOne" class="btn-ctrl btn-ctrl-accent"><i class="fa-solid fa-hand-holding-hand"></i> 撈走 1 條魚 🐠</button>
      <button id="btnResetFish" class="btn-ctrl"><i class="fa-solid fa-rotate-left"></i> 全部游回來 (重置為5)</button>
    `;

    const aquarium = document.getElementById("aquarium");
    const formula = document.getElementById("w07Formula");
    const btnNet = document.getElementById("btnNetOne");
    const btnReset = document.getElementById("btnResetFish");

    function renderFish() {
      aquarium.innerHTML = "";
      if (fishCount === 0) {
        aquarium.innerHTML = `
          <div style="font-size:1.4rem; font-weight:900; color:#0369a1; text-align:center;">
            🫧 魚缸空空如也！<br>一條魚也沒有了，數學上用【 0 】來表示！
          </div>
        `;
      } else {
        for (let i = 0; i < fishCount; i++) {
          const fish = document.createElement("div");
          fish.style.cssText = "font-size:2.8rem; cursor:pointer; transition:transform 0.3s; animation:bounce 2s infinite;";
          fish.textContent = "🐠";
          fish.title = "點擊撈走這條魚";
          fish.addEventListener("click", () => {
            if (fishCount > 0) { fishCount--; renderFish(); }
          });
          aquarium.appendChild(fish);
        }
      }

      const gone = INITIAL - fishCount;
      formula.innerHTML = `
        原來有 <b>${INITIAL}</b> 條 － 撈走 <b>${gone}</b> 條 ＝ 還剩下 <b>${fishCount}</b> 條
        ${fishCount === 0 ? "（神奇的 0 代表一個也沒有！）" : ""}
      `;
      celebrate();
    }

    btnNet.addEventListener("click", () => {
      if (fishCount > 0) { fishCount--; renderFish(); }
    });

    btnReset.addEventListener("click", () => {
      fishCount = INITIAL;
      renderFish();
    });

    renderFish();
  }

