  function renderW18() {
    let hours = 3;
    let minutes = 30; // 3:30

    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:16px;">
        <!-- SVG Analog Clock -->
        <svg id="clockSvg" viewBox="0 0 240 240" style="width:200px; height:200px; background:#fff; border-radius:50%; border:6px solid #2563eb; box-shadow:0 8px 25px rgba(37,99,235,0.2);">
          <!-- Numbers -->
          <text x="120" y="32" text-anchor="middle" font-weight="900" font-size="18" fill="#1e293b">12</text>
          <text x="210" y="126" text-anchor="middle" font-weight="900" font-size="18" fill="#1e293b">3</text>
          <text x="120" y="220" text-anchor="middle" font-weight="900" font-size="18" fill="#1e293b">6</text>
          <text x="30" y="126" text-anchor="middle" font-weight="900" font-size="18" fill="#1e293b">9</text>

          <!-- Center Pivot -->
          <circle cx="120" cy="120" r="6" fill="#334155" />

          <!-- Hour Hand (Short, Dark) -->
          <line id="hourHand" x1="120" y1="120" x2="120" y2="70" stroke="#1e293b" stroke-width="6" stroke-linecap="round" />

          <!-- Minute Hand (Long, Red) -->
          <line id="minuteHand" x1="120" y1="120" x2="120" y2="40" stroke="#ef4444" stroke-width="4" stroke-linecap="round" />
        </svg>

        <div id="w18Digital" style="font-size:1.4rem; font-weight:900; color:#1e3a8a; background:#eff6ff; padding:8px 24px; border-radius:12px; border:2px solid #bfdbfe;">
          3:30 (3 點半)
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <button id="btn300" class="btn-ctrl">🔔 3:00 整點</button>
      <button id="btn330" class="btn-ctrl btn-ctrl-accent">⏰ 3:30 半點</button>
      <button id="btn800" class="btn-ctrl">🔔 8:00 整點</button>
      <button id="btn830" class="btn-ctrl btn-ctrl-purple">⏰ 8:30 半點</button>
    `;

    const hourHand = document.getElementById("hourHand");
    const minuteHand = document.getElementById("minuteHand");
    const digital = document.getElementById("w18Digital");

    function updateClock(h, m) {
      hours = h;
      minutes = m;
      const mDeg = m * 6;
      const hDeg = (h % 12) * 30 + (m / 60) * 30;

      minuteHand.setAttribute("transform", `rotate(${mDeg} 120 120)`);
      hourHand.setAttribute("transform", `rotate(${hDeg} 120 120)`);

      const textDesc = m === 0 ? `${h} 點鐘 (整點)` : `${h} 點半 (半點)`;
      digital.textContent = `${h}:${String(m).padStart(2, "0")} (${textDesc})`;
      celebrate();
    }

    document.getElementById("btn300").addEventListener("click", () => updateClock(3, 0));
    document.getElementById("btn330").addEventListener("click", () => updateClock(3, 30));
    document.getElementById("btn800").addEventListener("click", () => updateClock(8, 0));
    document.getElementById("btn830").addEventListener("click", () => updateClock(8, 30));

    updateClock(3, 30);
  }

