  // ==========================================
  // MODULE 27: 平面圖形邊角放大鏡
  // ==========================================
  function renderW27() {
    labStage.innerHTML = `
      <div style="display:flex; flex-direction:column; align-items:center; gap:20px; width:100%;">
        <div id="shapeBox" style="width:100%; max-width:540px; height:180px; background:#fff; border-radius:18px; border:2px solid #e2e8f0; display:flex; align-items:center; justify-content:center;">
          <!-- Shape rendered here -->
        </div>
        <div id="w27Desc" style="font-size:1.2rem; font-weight:800; color:#1e3a8a; background:#eff6ff; padding:10px 24px; border-radius:14px; border:2px solid #bfdbfe;">
          <!-- Description -->
        </div>
      </div>
    `;

    controlPanel.innerHTML = `
      <button id="btnSquare" class="btn-ctrl btn-ctrl-accent">⬛ 正方形</button>
      <button id="btnRect" class="btn-ctrl">📄 長方形</button>
      <button id="btnTri" class="btn-ctrl btn-ctrl-purple">🔺 三角形</button>
      <button id="btnCircle" class="btn-ctrl">⚪ 圓形</button>
    `;

    const box = document.getElementById("shapeBox");
    const desc = document.getElementById("w27Desc");

    function showShape(type) {
      if (type === "square") {
        box.innerHTML = '<div style="width:110px; height:110px; background:#3b82f6; border:4px solid #1d4ed8; border-radius:4px; box-shadow:0 8px 16px rgba(59,130,246,0.3);"></div>';
        desc.innerHTML = "⬛ <b>正方形</b>：有 <b>4 條邊</b> 全部一樣長，有 <b>4 個直角</b>！";
      } else if (type === "rect") {
        box.innerHTML = '<div style="width:180px; height:90px; background:#10b981; border:4px solid #059669; border-radius:4px; box-shadow:0 8px 16px rgba(16,185,129,0.3);"></div>';
        desc.innerHTML = "📄 <b>長方形</b>：有 <b>4 條邊</b>，對面的兩條邊一樣長，有 <b>4 個直角</b>！";
      } else if (type === "tri") {
        box.innerHTML = '<div style="width:0; height:0; border-left:60px solid transparent; border-right:60px solid transparent; border-bottom:110px solid #f59e0b;"></div>';
        desc.innerHTML = "🔺 <b>三角形</b>：有 <b>3 條直直的邊</b>，有 <b>3 個角</b>，形狀最穩固！";
      } else {
        box.innerHTML = '<div style="width:110px; height:110px; background:#ec4899; border:4px solid #be185d; border-radius:50%; box-shadow:0 8px 16px rgba(236,72,153,0.3);"></div>';
        desc.innerHTML = "⚪ <b>圓形</b>：由一條封閉的曲線圍成，<b>沒有任何尖尖的角</b>，圓滾滾！";
      }
      celebrate();
    }

    document.getElementById("btnSquare").addEventListener("click", () => showShape("square"));
    document.getElementById("btnRect").addEventListener("click", () => showShape("rect"));
    document.getElementById("btnTri").addEventListener("click", () => showShape("tri"));
    document.getElementById("btnCircle").addEventListener("click", () => showShape("circle"));

    showShape("square");
  }

